                if (i-dr,j-dc) in cs: continue  # not run start
                run=[(i,j)]; a,b=i+dr,j+dc
                while (a,b) in cs: run.append((a,b)); seen.add((a,b)); a,b=a+dr,b+dc
                if len(run)<2: continue
                for end,sgn in [(run[-1],1),(run[0],-1)]:
